extern crate alloc;
use nepl3_core::{budget::*,schema::*,source::*,value::{NdfValue,SchemaRef}};
use nepl3_markup::{html::*,portable};
use nepl3_wire::foundation::FoundationCodec;
#[path="old_descriptor.rs"] mod old;
fn b()->Budget{Budget::new(Limits{work:100_000_000,allocation_units:100_000_000,output_bytes:10_000_000,nodes:100_000,depth:1000,..Limits::default()})}
fn err(x:impl std::fmt::Debug)->String{format!("{x:?}")}
fn req(id:&str,branch:usize)->HtmlRequest{let href=match branch{0=>HtmlHref::Fragment{id:id.into()},1=>HtmlHref::Artifact{path:"target.html".into(),fragment:Some(id.into())},_=>HtmlHref::BetweenArtifacts{source:"from/input.html".into(),target:"to/target.html".into(),fragment:Some(id.into())}};HtmlRequest{slot:HtmlSlot::Block,policy:HtmlPolicy{classes:vec![]},fragment:HtmlFragment{root:0,nodes:vec![HtmlNode::Element{tag:HtmlTag::Div,attributes:vec![],children:vec![1,3,5]},HtmlNode::Element{tag:HtmlTag::A,attributes:vec![HtmlAttribute::Href{value:href}],children:vec![2]},HtmlNode::Text{text:"follow".into()},HtmlNode::Element{tag:HtmlTag::P,attributes:vec![],children:vec![4]},HtmlNode::Text{text:"before ".repeat(900)},HtmlNode::Element{tag:HtmlTag::P,attributes:vec![HtmlAttribute::Id{value:id.into()}],children:vec![6]},HtmlNode::Text{text:"destination".into()}]}}}
fn stamp(v:&mut NdfValue,s:&SchemaRef){match v{NdfValue::Record(r)=>{r.schema=s.clone();for f in &mut r.fields{stamp(f,s)}},NdfValue::Variant(r)=>{r.schema=s.clone();for f in &mut r.fields{stamp(f,s)}},NdfValue::List(v)=>for f in v{stamp(f,s)},_=>{}}}
fn main()->Result<(),String>{let mut registry=SchemaRegistry::default();let mut old_ref=None;for d in [nepl3_core::schema::foundation::descriptor(&mut b()),nepl3_markup::schema::descriptor(&mut b()),old::descriptor(&mut b())]{let d=d.map_err(err)?;let s=d.reference(&mut b()).map_err(err)?;if s.package=="nepl3.markup"&&s.revision==1{old_ref=Some(s.clone())};registry.register(s,d,&mut b()).map_err(err)?}registry.finalize(&mut b()).map_err(err)?;
let ids=["1-\u{65e5}\u{672c}","%41","A","x%20#?", "\"'<>&`", "x:~:text=destination","\u{1f642}","e\u{301}","\u{e9}","\u{a0}","\u{2028}","\u{10000}","0", "A_b.~", "-", "\u{10ffff}"];
let mut records=vec![];for id in ids{for branch in 0..3{let input=req(id,branch);let original=input.clone();let proof=validate(&input.fragment,input.slot,&input.policy,&mut b()).map_err(err)?;let mut budget=b();let html=serialize(&proof,&mut budget).map_err(err)?;assert_eq!(budget.usage().output_bytes,html.len() as u64);let bytes={let sources=SourceStore::default();let mut admission=SourceAdmission::default();let mut c=FoundationCodec::new(&registry,&sources,&mut admission).map_err(err)?;let value=portable::to_value(&input,&registry,&mut c,&mut b()).map_err(err)?;nepl3_wire::encode(&value,&mut b()).map_err(err)?};let sources=SourceStore::default();let mut admission=SourceAdmission::default();let mut c=FoundationCodec::new(&registry,&sources,&mut admission).map_err(err)?;let value=nepl3_wire::decode(&bytes,&mut b()).map_err(err)?;let mut budget=b();let received=portable::from_value(&value,&registry,&mut c,&mut budget).map_err(err)?;assert_eq!(received,input);assert_eq!(budget.usage().source_bytes,0);let cp=validate(&received.fragment,received.slot,&received.policy,&mut b()).map_err(err)?;assert_eq!(serialize(&cp,&mut b()).map_err(err)?,html);assert_eq!(input,original);records.push(serde_json::json!({"id":id,"branch":branch,"html":html}));}}
let mut negatives=0;for scalar in (0..=0x20).chain(0x7f..=0x9f).chain([0xfffe,0xffff]){let id=char::from_u32(scalar).ok_or("scalar")?.to_string();for branch in 0..3{let input=req(&id,branch);assert!(validate(&input.fragment,input.slot,&input.policy,&mut b()).is_err());negatives+=1;}}
for value in ["", "A", "1", "\u{65e5}", "x_y"]{for which in 0..3{let mut input=req("good",0);if which<2{if let HtmlNode::Element{attributes,..}=&mut input.fragment.nodes[0]{attributes.push(if which==0{HtmlAttribute::DataId{value:value.into()}}else{HtmlAttribute::DataGroup{value:value.into()}})}}else{input.policy.classes.push(value.into())}assert!(validate(&input.fragment,input.slot,&input.policy,&mut b()).is_err());negatives+=1;}}
let input=req("plain",0);let sources=SourceStore::default();let mut a=SourceAdmission::default();let mut c=FoundationCodec::new(&registry,&sources,&mut a).map_err(err)?;let mut value=portable::to_value(&input,&registry,&mut c,&mut b()).map_err(err)?;stamp(&mut value,&old_ref.ok_or("old schema")?);registry.validate(&TypeDescriptor::Named(TypeRef{package:"nepl3.markup".into(),revision:1,name:"HtmlRequest".into()}),&value,&mut b()).map_err(err)?;let bytes=nepl3_wire::encode(&value,&mut b()).map_err(err)?;let value=nepl3_wire::decode(&bytes,&mut b()).map_err(err)?;assert!(portable::from_value(&value,&registry,&mut c,&mut b()).is_err());
let mut input=req("\u{e9}",0);if let HtmlNode::Element{attributes,..}=&mut input.fragment.nodes[1]{attributes[0]=HtmlAttribute::Href{value:HtmlHref::Fragment{id:"e\u{301}".into()}}}assert!(matches!(validate(&input.fragment,input.slot,&input.policy,&mut b()),Err(HtmlError::MissingFragment(_))));
let input=req(&"\u{65e5}\u{672c}%#".repeat(64),2);let original=input.clone();let proof=validate(&input.fragment,input.slot,&input.policy,&mut b()).map_err(err)?;let expected=serialize(&proof,&mut b()).map_err(err)?;let mut stops=0;let mut successes=0;for resource in 0..3{for cap in [0,1,16,128,1024,8192,65536,1_000_000]{let mut limits=b().limits();let reason=match resource{0=>{limits.work=cap;StopReason::WorkLimit},1=>{limits.allocation_units=cap;StopReason::AllocationLimit},_=>{limits.output_bytes=cap;StopReason::OutputLimit}};let mut budget=Budget::new(limits);match serialize(&proof,&mut budget){Ok(v)=>{assert_eq!(v,expected);successes+=1},Err(HtmlError::Stopped(s))=>{assert_eq!(s,reason);assert_eq!(budget.poll(),Err(reason));stops+=1},Err(e)=>return Err(err(e))}}}let mut cancelled=b();cancelled.stop(StopReason::Cancelled);assert!(matches!(serialize(&proof,&mut cancelled),Err(HtmlError::Stopped(StopReason::Cancelled))));assert_eq!(input,original);
println!("{}",serde_json::json!({"cases":records,"invalid_cases":negatives,"old_schema_rejected":true,"stops":stops,"successes":successes}));Ok(())}
